/**
 * Per-tenant WebAuthn attestation policy (D5). One row per tenant; an absent row means
 * [`WebauthnAttestationPolicy::default`], which is today's behavior unchanged.
 */
struct axiam_mgmt_webauthn_attestation_policy {
    /**
     * `None` = every AAGUID is allowed except `blocked_aaguids`. `Some(vec![])` is a
     * deliberate "nothing may register" policy and is accepted as such: `evaluate` denies
     * every AAGUID against an empty allow-list. Nothing rejects it, precisely because the
     * failure direction is safe — a client that sends `[]` when it meant `null` gets a
     * locked-down tenant, which is visible immediately, rather than an open one, which is
     * not. Optional.
     */
    char **allowed_aaguids;
    size_t allowed_aaguids_count; /**< Entries in `allowed_aaguids`. */
    /**
     * Deny registration if the MDS entry has ever reported `REVOKED` or any `*_COMPROMISE`
     * status (sticky — D8 step 7).
     */
    int block_revoked_status;
    /**
     * The server's `blocked_aaguids` field. Optional.
     */
    char **blocked_aaguids;
    size_t blocked_aaguids_count; /**< Entries in `blocked_aaguids`. */
    /**
     * The server's `min_certification` field. Optional.
     */
    axiam_mgmt_certification_level_t min_certification;
    int has_min_certification; /**< 1 when `min_certification` is set. */
    /**
     * The server's `mode` field.
     */
    axiam_mgmt_attestation_mode_t mode;
    /**
     * Require *some* `FIDO_CERTIFIED*` status, any level. Independent of (and checked
     * before) `min_certification`.
     */
    int require_fido_certified;
    /**
     * The server's `unknown_aaguid` field. Optional.
     */
    axiam_mgmt_unknown_aaguid_action_t unknown_aaguid;
    int has_unknown_aaguid; /**< 1 when `unknown_aaguid` is set. */
};

